'use client'
import React, { useState, useEffect } from "react";
import { doc, getDoc } from "firebase/firestore";
import { db } from "@/app/db/firebase";
import Sidebar from "@/components/sidebar";


function ProdDet({params}) {
 const logoDataURL =
    "data:image/jpeg;base64,"; 
   const [fetchedDocumentData, setFetchedDocumentData] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);


  useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true);
      setError(null);

      try {
        const docRef = doc(db, "produk", params.id); // Reference the specific document
        const docSnap = await getDoc(docRef);
        setFetchedDocumentData(docSnap.data());
      } catch (error) {
        setError(error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, [params]);

  if (isLoading) {
    return <div>Loading...</div>;
  }

  if (error) {
    return <div>Error: {error.message}</div>;
  }

  if (!fetchedDocumentData) {
    return <div>No data found</div>;
  }


  return (
    <div className="w-full flex">
      <Sidebar/>
    <div className="flex flex-col">

    </div>
    <div className="text-red-500  text-xl w-screen h-screen flex flex-col p-5">
      <p className="font-bold">PRODUCT DETAIL</p>
      <div className="pt-5 flex gap-3">
        <div className="flex flex-col gap-3">

    <div className="w-[200px] h-[200px] flex justify-center items-center border-2 border-red-500 rounded-md"><p>PRODUCT IMAGE</p></div>
    <div className="w-[200px] h-[200px] relative ">
            
              <img
                className="w-[200px] h-[200px] absolute"
                src={fetchedDocumentData.qrImage}
                alt="Fetched QR Code"
              />
            
            <div className="w-[200px] h-[200px] flex items-center justify-center absolute rounded-lg">
              <div className="bg-[#ffffff] p-[2px] w-14">
                <img src={logoDataURL} alt="" />
              </div>
            </div>
            <div className="w-[200px] h-[200px] absolute border-2 border-red-500 rounded-md"></div>
          </div>
          <a
                    className="bg-red-500 w-[200px] rounded-md p-2 text-white font-semibold text-center"
                    href={`/print/${params.id}`}
                  >
                    PRINT QR
                  </a>
        </div>
      <div>
        <p className="text-4xl font-semibold uppercase">{fetchedDocumentData.nama}</p>
      <p className="font-bold">Type: {fetchedDocumentData.tipe}</p>
      <p>Price: {fetchedDocumentData.harga}</p>
      <br />
      <p>{fetchedDocumentData.desc}</p>
      </div>
      </div>

     
    </div>
   
    </div>

  );
}

export default ProdDet;
